import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

let n = Number(input[0]);

let steps = 0;
while (n !== 1) {
  n = n % 2 === 0 ? n / 2 : 3 * n + 1;
  steps++;
}
console.log(steps);
